package mx.uv.dsw.telemetry; import java.util.List; import javax.validation.Valid; import org.springframework.beans.factory.annotation.Value; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/telemetry") @CrossOrigin(origins={"http://localhost:4200","http://localhost:8088"}) public class TelemetryController {private final TelemetryRepository repo;private final String labKey;public TelemetryController(TelemetryRepository r,@Value("${lab.api-key:lab-only-key}") String key){repo=r;labKey=key;}@GetMapping public List<Telemetry> all(){return repo.findAll();}@PostMapping public ResponseEntity<?> create(@RequestHeader(value="X-Lab-Key",required=false) String key,@Valid @RequestBody Telemetry t){if(!labKey.equals(key))return ResponseEntity.status(HttpStatus.UNAUTHORIZED).body("X-Lab-Key requerida");return ResponseEntity.status(HttpStatus.CREATED).body(repo.save(t));}@GetMapping("/health") public String health(){return "UP";}}
